/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Group names accepted wherever a status filter is read (ADR 0009, rule 3). */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: readonly IssueStatusGroup[] = ["open", "closed"];

/**
 * Expands group names into their member statuses. `open` is every status that
 * is not closed; `closed` is `CLOSED_ISSUE_STATUSES`. The result is in
 * `ISSUE_STATUSES` order and holds each status once.
 */
export function expandIssueStatuses(
  values: readonly (IssueStatus | IssueStatusGroup)[],
): IssueStatus[] {
  const picked = new Set<IssueStatus>();
  for (const value of values) {
    if (value === "open") {
      for (const status of ISSUE_STATUSES) {
        if (!CLOSED_ISSUE_STATUSES.includes(status)) picked.add(status);
      }
    } else if (value === "closed") {
      for (const status of CLOSED_ISSUE_STATUSES) picked.add(status);
    } else {
      picked.add(value);
    }
  }
  return ISSUE_STATUSES.filter((status) => picked.has(status));
}

