    ? {}
    : { includeArchived: true };
  const statuses =
    input.status === undefined ? [] : expandIssueStatuses(input.status);
  // Each label is its own EXISTS-style subquery, so an issue must carry all of them.
  const labelIds = [...new Set(input.labelIds ?? [])];

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    input.archivedOnly === true
      ? isNotNull(issues.archivedAt)
      : livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
