      ? isNotNull(issues.archivedAt)
      : livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, statuses),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `null` is "unassigned"; `undefined` means the filter is not set.
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined
      ? undefined
      : dueBeforePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    ...labelIds.map((labelId) =>
      inArray(
        issues.id,
        getDb()
          .select({ id: issueLabels.issueId })
          .from(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, input.orgId),
              eq(issueLabels.labelId, labelId),
            ),
          ),
      ),
    ),
  );
}

/** Issues due strictly before the bound; a calendar date covers its whole day. */
function dueBeforePredicate(value: string): SQL {
  const bound = dueBeforeBound(value);
  if (bound === null) throw new Error(`Invalid due_before value ${value}`);
  return lt(issues.dueAt, toIsoTimestamp(bound));
}

